{
  "rules": [
    {
      "category": "algorithmic_rent_setting",
      "title": "Algorithmic rent fixing ban",
      "requirement": "Landlords and their agents are prohibited from subscribing to, contracting with, or exchanging value for algorithmic pricing coordination services, and service providers cannot facilitate agreements not to compete.",
      "requirement_es": "Se prohíbe a los arrendadores y sus agentes suscribirse, contratar o intercambiar valor por servicios de coordinación de precios algorítmicos, y los proveedores de servicios no pueden facilitar acuerdos para no competir.",
      "key_value": {
        "label": "algorithmic pricing coordination",
        "value": "prohibited"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Inpatient medical care, licensed long-term care, and detention or correctional facilities",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": null,
      "superseded_date": null,
      "status": "pending",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Violations constitute unfair competition under chapters 93 and 93A, with liability for actual damages, simple interest, costs, reasonable attorney fees, expert fees, and investigation costs; predispute arbitration agreements and joint-action waivers are unenforceable at the election of the plaintiff.",
      "source_citation": "Mass. H.5222 § 2",
      "quote": {
        "chunk": "c5",
        "start_words": "No real estate lessor, or any agent",
        "end_words": "with respect to residential dwelling units."
      },
      "confidence": 0.95
    }
  ]
}
